        }
      ]
    },
    {
      "category": "learning_objective",
      "rationale": "Weight masked-target cross-entropy threefold at the final sequence position, normalized by total weight, to emphasize the position used by appended-mask inference.",
      "edits": [
        {
          "find": "    return torch.nn.functional.cross_entropy(logits, targets, reduction=\"mean\")",
          "replace": "    losses = torch.nn.functional.cross_entropy(logits, targets, reduction=\"none\")\n    position_weights = torch.ones_like(pos, dtype=logits.dtype)\n    position_weights[:, -1] = 3.0\n    weights = position_weights[mask]\n    return (losses * weights).sum() / weights.sum()"
        }
      ]
    },
    {
      "category": "feature_construction",
      "rationale": "Scale visible real-item input vectors by 1+0.08*log1p(n)/log(129), using only the visible real-item count. Padding and mask vectors remain unchanged. The generated predictor imports this model class, so the feature is shared automatically without checkpoint shape changes.",
      "edits": [
        {
          "find": "        item_vectors = torch.nn.functional.embedding(\n            seq, self.effective_item_weight(), padding_idx=0\n        )\n        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)",
          "replace": "        item_vectors = torch.nn.functional.embedding(\n            seq, self.effective_item_weight(), padding_idx=0\n        )\n        visible_real = (seq > 0) & (seq <= self.itemnum)\n        visible_count = visible_real.sum(dim=1, keepdim=True).to(item_vectors.dtype)\n        length_cue = 0.08 * torch.log1p(visible_count) / math.log(129.0)\n        input_scale = 1.0 + visible_real.to(item_vectors.dtype) * length_cue\n        item_vectors = item_vectors * input_scale.unsqueeze(-1)\n        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)"
        }
      ]
    }
